// Validity of a value read from shared memory (D6).  Only bool, and the enums and the
// records and arrays containing them, have invalid bit patterns; the rest are always
// valid.  A bool is read as a byte, since reading a bool object that holds neither 0 nor
// 1 is itself undefined.
static inline bool bool_is_valid(const bool *v) { return *(const uint8_t *) v <= 1; }
static inline bool char_is_valid(const char *v) { (void) v; return true; }
static inline bool int8_t_is_valid(const int8_t *v) { (void) v; return true; }
static inline bool int16_t_is_valid(const int16_t *v) { (void) v; return true; }
static inline bool int32_t_is_valid(const int32_t *v) { (void) v; return true; }
static inline bool int64_t_is_valid(const int64_t *v) { (void) v; return true; }
static inline bool uint8_t_is_valid(const uint8_t *v) { (void) v; return true; }
static inline bool uint16_t_is_valid(const uint16_t *v) { (void) v; return true; }
static inline bool uint32_t_is_valid(const uint32_t *v) { (void) v; return true; }
static inline bool uint64_t_is_valid(const uint64_t *v) { (void) v; return true; }
static inline bool float_is_valid(const float *v) { (void) v; return true; }
static inline bool double_is_valid(const double *v) { (void) v; return true; }

typedef
  enum {Onn, Off} Isolette_Data_Model_On_Off;

_Static_assert(sizeof(Isolette_Data_Model_On_Off) == 4, "Isolette_Data_Model_On_Off: memory layout differs from HAMR's");
_Static_assert(_Alignof(Isolette_Data_Model_On_Off) == 4, "Isolette_Data_Model_On_Off: memory layout differs from HAMR's");


static inline bool Isolette_Data_Model_On_Off_is_valid(const Isolette_Data_Model_On_Off *v) {
  return (uint32_t) *v < 2;
}

typedef struct Isolette_Data_Model_Temp {
  int32_t degrees;
} Isolette_Data_Model_Temp;

_Static_assert(sizeof(Isolette_Data_Model_Temp) == 4, "Isolette_Data_Model_Temp: memory layout differs from HAMR's");
_Static_assert(_Alignof(Isolette_Data_Model_Temp) == 4, "Isolette_Data_Model_Temp: memory layout differs from HAMR's");
_Static_assert(offsetof(Isolette_Data_Model_Temp, degrees) == 0, "Isolette_Data_Model_Temp: memory layout differs from HAMR's");

static inline bool Isolette_Data_Model_Temp_is_valid(const Isolette_Data_Model_Temp *v) {
  return int32_t_is_valid(&v->degrees);
}

typedef struct Isolette_Data_Model_Set_Points {
  Isolette_Data_Model_Temp lower;
  Isolette_Data_Model_Temp upper;
} Isolette_Data_Model_Set_Points;

_Static_assert(sizeof(Isolette_Data_Model_Set_Points) == 8, "Isolette_Data_Model_Set_Points: memory layout differs from HAMR's");
_Static_assert(_Alignof(Isolette_Data_Model_Set_Points) == 4, "Isolette_Data_Model_Set_Points: memory layout differs from HAMR's");
_Static_assert(offsetof(Isolette_Data_Model_Set_Points, lower) == 0, "Isolette_Data_Model_Set_Points: memory layout differs from HAMR's");
_Static_assert(offsetof(Isolette_Data_Model_Set_Points, upper) == 4, "Isolette_Data_Model_Set_Points: memory layout differs from HAMR's");

static inline bool Isolette_Data_Model_Set_Points_is_valid(const Isolette_Data_Model_Set_Points *v) {
  return Isolette_Data_Model_Temp_is_valid(&v->lower) &&
                  Isolette_Data_Model_Temp_is_valid(&v->upper);
}
